use std::thread;

fn run_target_thread(id: u8) {
    let mut random_bytes = [0_u8; 16];
    // SAFETY: the buffer is writable and exactly 16 bytes long.
    let random_result =
        unsafe { libc::getrandom(random_bytes.as_mut_ptr().cast(), random_bytes.len(), 0) };
    if random_result < 0 {
        eprintln!("[Target Thread {id}] getrandom failed");
    } else {
        let hex: String = random_bytes
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect();
        println!("[Target Thread {id}] getrandom: {hex}");
    }

    for _ in 0..2 {
        let mut ts = libc::timespec {
            tv_sec: 0,
            tv_nsec: 0,
        };
        // SAFETY: `ts` points to valid writable storage.
        if unsafe { libc::clock_gettime(libc::CLOCK_MONOTONIC, &mut ts) } == 0 {
            println!("[Target Thread {id}] time: {}s {}ns", ts.tv_sec, ts.tv_nsec);
        } else {
            eprintln!("[Target Thread {id}] clock_gettime failed");
        }

        for n in 0_u64..10_000 {
            std::hint::black_box(n.wrapping_mul(n));
        }
    }

    let request = libc::timespec {
        tv_sec: 0,
        tv_nsec: 100_000_000,
    };
    // SAFETY: `request` is a valid timespec; no remainder is needed here.
    unsafe {
        libc::nanosleep(&request, std::ptr::null_mut());
    }
}

fn main() {
    let first = thread::spawn(|| run_target_thread(1));
    let second = thread::spawn(|| run_target_thread(2));
    first.join().expect("target thread 1 panicked");
    second.join().expect("target thread 2 panicked");
}

fn main() {
    // Keep the ten-second fixture default; allow the benchmark duration sweep.
    let seconds = std::env::args()
        .nth(1)
        .map(|value| {
            value
                .parse::<i64>()
                .expect("duration must be whole seconds")
        })
        .unwrap_or(10);
    assert!(seconds > 0, "duration must be positive");
    println!("[TimeWarp Target] Starting {seconds}-second nanosleep...");

    let request = libc::timespec {
        tv_sec: seconds,
        tv_nsec: 0,
    };
    // SAFETY: `request` is a valid timespec and no remainder is needed.
    let result = unsafe { libc::nanosleep(&request, std::ptr::null_mut()) };
    if result != 0 {
        eprintln!("[TimeWarp Target] nanosleep failed");
        std::process::exit(1);
    }

    println!("[TimeWarp Target] Woke up successfully!");
}

use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let trace = Arc::new(Mutex::new(Vec::<u32>::new()));
    let counter = Arc::new(Mutex::new(0_u64));
    let mut workers = Vec::with_capacity(4);

    for id in 0..4_u32 {
        let trace = Arc::clone(&trace);
        let counter = Arc::clone(&counter);
        workers.push(thread::spawn(move || {
            for _ in 0..5 {
                let mut trace = trace.lock().expect("trace mutex poisoned");
                let mut counter = counter.lock().expect("counter mutex poisoned");
                trace.push(id);
                *counter += 1;
                thread::yield_now();
            }
        }));
    }

    for worker in workers {
        worker.join().expect("worker thread panicked");
    }

    let trace = trace.lock().expect("trace mutex poisoned");
    let counter = counter.lock().expect("counter mutex poisoned");
    println!("[Concurrency Target] Lock acquisition order: {trace:?}");
    println!("[Concurrency Target] Final counter: {counter}");
}

fn main() {
    println!("[RDTSC Target] Querying hardware timestamp counter...");

    // First read using core::arch::x86_64::_rdtsc
    let t1 = unsafe { core::arch::x86_64::_rdtsc() };

    // Small computation to advance time
    let mut sum = 0_u64;
    for i in 1..10_000 {
        sum = sum.wrapping_add(i * i);
    }
    std::hint::black_box(sum);

    // Second read using core::arch::x86_64::__rdtscp
    let mut aux = 0_u32;
    let t2 = unsafe { core::arch::x86_64::__rdtscp(&mut aux) };

    println!("[RDTSC Target] First read:  {t1}");
    println!("[RDTSC Target] Second read: {t2}");
    println!("[RDTSC Target] Synthetic core ID (aux): {aux}");

    if t2 <= t1 {
        eprintln!("[RDTSC Target] Error: cycle counter did not advance! ({t2} <= {t1})");
        std::process::exit(1);
    }

    println!("[RDTSC Target] RDTSC emulation verified successfully!");
}

use std::os::fd::{AsRawFd, FromRawFd};

fn main() {
    let mut fds = [-1; 2];
    // SAFETY: `fds` points to space for two descriptors.
    if unsafe {
        libc::socketpair(
            libc::AF_UNIX,
            libc::SOCK_STREAM | libc::SOCK_NONBLOCK,
            0,
            fds.as_mut_ptr(),
        )
    } != 0
    {
        eprintln!(
            "[Fault Target] socketpair failed: {}",
            std::io::Error::last_os_error()
        );
        std::process::exit(1);
    }
    // SAFETY: socketpair returned two owned descriptors.
    let left = unsafe { std::os::fd::OwnedFd::from_raw_fd(fds[0]) };
    // SAFETY: socketpair returned two owned descriptors.
    let right = unsafe { std::os::fd::OwnedFd::from_raw_fd(fds[1]) };
    let payload = [0x5a_u8; 32];
    let mut buffer = [0_u8; 64];
    let mut successes = 0;
    let mut faults = Vec::new();

    for _ in 0..50 {
        // SAFETY: payload is readable and the descriptor is valid.
        let written =
            unsafe { libc::write(left.as_raw_fd(), payload.as_ptr().cast(), payload.len()) };
        if written == -1 {
            faults.push(std::io::Error::last_os_error().raw_os_error().unwrap_or(0));
        } else {
            successes += 1;
        }

        // SAFETY: buffer is writable and the descriptor is valid.
        let read =
            unsafe { libc::read(right.as_raw_fd(), buffer.as_mut_ptr().cast(), buffer.len()) };
        if read == -1 {
            faults.push(std::io::Error::last_os_error().raw_os_error().unwrap_or(0));
        } else {
            successes += 1;
        }
    }

    println!(
        "[Fault Target] Operations: 50 | Successes: {successes} | Injected faults: {} (codes: {faults:?})",
        faults.len()
    );
}

use std::{
    io,
    os::fd::{AsRawFd, FromRawFd, OwnedFd},
};

fn main() -> io::Result<()> {
    // SAFETY: epoll_create1 takes only flags and returns a new descriptor.
    let epfd = unsafe { libc::epoll_create1(libc::EPOLL_CLOEXEC) };
    if epfd < 0 {
        return Err(io::Error::last_os_error());
    }
    // SAFETY: epfd is a newly created, owned descriptor.
    let epfd = unsafe { OwnedFd::from_raw_fd(epfd) };

    let mut pipefds = [0; 2];
    // SAFETY: pipefds points to space for both descriptors.
    if unsafe { libc::pipe2(pipefds.as_mut_ptr(), libc::O_CLOEXEC | libc::O_NONBLOCK) } < 0 {
        return Err(io::Error::last_os_error());
    }
    // SAFETY: pipe2 successfully returned two distinct owned descriptors.
    let read_fd = unsafe { OwnedFd::from_raw_fd(pipefds[0]) };
    let _write_fd = unsafe { OwnedFd::from_raw_fd(pipefds[1]) };
    let mut event = libc::epoll_event {
        events: libc::EPOLLIN as u32,
        u64: 0,
    };
    // SAFETY: descriptors are valid and event points to an initialized epoll_event.
    if unsafe {
        libc::epoll_ctl(
            epfd.as_raw_fd(),
            libc::EPOLL_CTL_ADD,
            read_fd.as_raw_fd(),
            &mut event,
        )
    } < 0
    {
        return Err(io::Error::last_os_error());
    }

    println!("[Epoll Target] Calling epoll_wait with 15,000ms timeout...");
    // SAFETY: event points to writable storage for one event.
    let result = unsafe { libc::epoll_wait(epfd.as_raw_fd(), &mut event, 1, 15_000) };
    println!("[Epoll Target] epoll_wait returned: {result} (expected 0 for timeout)");
    assert_eq!(result, 0);
    Ok(())
}

fn main() {
    let mut state = 0xcbf2_9ce4_8422_2325_u64;
    for _ in 0..3 {
        let mut ts = libc::timespec {
            tv_sec: 0,
            tv_nsec: 0,
        };
        // SAFETY: ts points to valid writable storage.
        unsafe {
            libc::syscall(
                libc::SYS_clock_gettime,
                libc::CLOCK_MONOTONIC,
                &mut ts as *mut libc::timespec,
            );
        }
        state = hash_bytes(state, &ts.tv_sec.to_ne_bytes());
        state = hash_bytes(state, &ts.tv_nsec.to_ne_bytes());

        let mut random = [0_u8; 16];
        // SAFETY: random is a valid writable buffer.
        unsafe {
            libc::syscall(libc::SYS_getrandom, random.as_mut_ptr(), random.len(), 0);
        }
        state = hash_bytes(state, &random);

        let request = libc::timespec {
            tv_sec: 0,
            tv_nsec: 1_000_000,
        };
        // SAFETY: request points to a valid timespec.
        unsafe {
            libc::syscall(
                libc::SYS_nanosleep,
                &request as *const libc::timespec,
                std::ptr::null_mut::<libc::timespec>(),
            );
        }

        // SAFETY: rdtsc is available on x86-64.
        #[cfg(target_arch = "x86_64")]
        let cycles = unsafe { core::arch::x86_64::_rdtsc() };
        #[cfg(not(target_arch = "x86_64"))]
        let cycles = 0_u64;
        state = hash_bytes(state, &cycles.to_ne_bytes());
    }
    println!("[RecordReplay Target] State hash: {state:016x}");
}

fn hash_bytes(mut hash: u64, bytes: &[u8]) -> u64 {
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

fn verify_process(pid: libc::pid_t, ppid: libc::pid_t) -> bool {
    // SAFETY: these syscalls take no pointers.
    unsafe {
        libc::syscall(libc::SYS_getpid) == pid as libc::c_long
            && libc::syscall(libc::SYS_getppid) == ppid as libc::c_long
    }
}

fn main() {
    if !verify_process(1000, 999) {
        eprintln!("[ProcessTree] Parent PID/PPID verification failed");
        std::process::exit(1);
    }

    // SAFETY: fork is called before creating any threads.
    let child1 = unsafe { libc::fork() };
    if child1 == 0 {
        if !verify_process(1001, 1000) {
            // SAFETY: _exit terminates only this forked child.
            unsafe { libc::_exit(1) };
        }
        let mut ts = libc::timespec {
            tv_sec: 0,
            tv_nsec: 0,
        };
        let mut random = [0_u8; 16];
        // SAFETY: both pointers refer to valid writable memory.
        let ok = unsafe {
            libc::clock_gettime(libc::CLOCK_MONOTONIC, &mut ts) == 0
                && libc::getrandom(random.as_mut_ptr().cast(), random.len(), 0) >= 0
        };
        if ok {
            println!("[ProcessTree] Child 1 PID 1001 verified");
        }
        // SAFETY: _exit avoids running copied parent process destructors.
        unsafe { libc::_exit(if ok { 0 } else { 1 }) };
    }
    if child1 < 0 || wait_success(child1) != 0 {
        std::process::exit(1);
    }

    // SAFETY: fork is called in the single-threaded parent.
    let child2 = unsafe { libc::fork() };
    if child2 == 0 {
        let verified = verify_process(1002, 1000);
        std::hint::black_box((0..10_000_u64).fold(0_u64, u64::wrapping_add));
        // SAFETY: _exit terminates only this forked child.
        unsafe { libc::_exit(if verified { 0 } else { 1 }) };
    }
    if child2 < 0 || wait_success(child2) != 0 {
        std::process::exit(1);
    }
    println!("[ProcessTree] All hierarchy tests passed deterministically");
}

fn wait_success(pid: libc::pid_t) -> libc::c_int {
    let mut status = 0;
    // SAFETY: status is writable and pid is the returned child process ID.
    if unsafe { libc::waitpid(pid, &mut status, 0) } != pid {
        return -1;
    }
    if libc::WIFEXITED(status) {
        libc::WEXITSTATUS(status)
    } else {
        -1
    }
}

